sed -i 's/currentProject.notes.every(n => n.publishStatus !== '\''已发布'\'')/((pipeline?.observing || 0) + (pipeline?.completed || 0)) === 0/g' src/components/merchant/ProjectCenter.tsx

sed -i 's/已发布{currentProject.notes.filter(n => n.publishStatus === "已发布").length}篇 · 观察中{currentProject.notes.filter(n => n.resultStatus === "观察中").length}篇 · 已完成{currentProject.notes.filter(n => n.resultStatus === "已完成").length}篇 · {currentProject.notes.filter(n => n.resultStatus === "数据异常").length > 0 ? <span className="text-red-600 font-medium">{currentProject.notes.filter(n => n.resultStatus === "数据异常").length}篇识别异常<\/span> : <span>0篇识别异常<\/span>}/已发布{(pipeline?.observing || 0) + (pipeline?.completed || 0)}篇 · 观察中{pipeline?.observing || 0}篇 · 已完成{pipeline?.completed || 0}篇 · {pipeline?.exception ? <span className="text-red-600 font-medium">{pipeline.exception}篇识别异常<\/span> : <span>0篇识别异常<\/span>}/g' src/components/merchant/ProjectCenter.tsx
